-- PROSPECTION-V3, jour 1 (lundi 30/11/2026). « Vas-y » du directeur, 27/11/2026.
-- 1. Les 79 lettres longues mises en pause au 31/12 par le pilote (categorie direction, sans lien de
--    desinscription, ancien texte) sont annulees : elles ne partiront jamais.
-- 2. 100 lettres courtes (79 premieres lettres et 21 relances uniques de la vague du 22/11), categorie
--    `nouvelles` (non essentielle) par courriel_enfiler : jeton de desinscription, et rien n'est enfile pour
--    une adresse desinscrite. Langue = langue du texte. Heure d'envoi posee ligne par ligne (paquets de
--    taille aleatoire, heures ouvrables du destinataire). 20 % sans image (temoin).
-- Aucune suppression. Rejouable : la cle d'idempotence empeche un doublon.
DO $prospection$
DECLARE
  v_n integer;
  v_id uuid;
  r record;
BEGIN
  SELECT count(*) INTO v_n FROM public.courriels_sortants
   WHERE origine = 'manuel' AND modele = 'message_libre' AND categorie = 'direction'
     AND statut = 'en_attente' AND prochaine_tentative = '2026-12-31 08:00:00+00';
  IF v_n NOT IN (0, 79) THEN
    RAISE EXCEPTION 'prospection-v3 : % lettres en pause au lieu de 79, rien n''est fait', v_n;
  END IF;
  UPDATE public.courriels_sortants
     SET statut = 'annule', derniere_erreur = 'remplacee par la prospection v3 (directeur, 27/11/2026)'
   WHERE origine = 'manuel' AND modele = 'message_libre' AND categorie = 'direction'
     AND statut = 'en_attente' AND prochaine_tentative = '2026-12-31 08:00:00+00';

  FOR r IN SELECT * FROM (VALUES
    ('info@manawatumuslims.org.nz', 'en', '{"sujet": "When a child misses out on a place", "corps": "Assalamu alaykum wa rahmatullah,\n\nYour centre teaches the Qur’an face to face, and nothing beats that when it’s possible. But some families miss out: the classes are full, the times don’t suit, or they live too far out.\n\nRewayah Academy is there for them: live online Qur’an classes in small groups, with the same teacher three times a week. We don’t replace your classes; we reach the children who can’t get to them.\n\nIf a family comes to mind, simply pass on this link:\nhttps://rewayahacademy.com/en/familles?ref=manawatu-muslim-association-madrasah\n\nThe Prophet ﷺ said: “The one who guides to good is like the one who does it.” (at-Tirmidhi)\n\nJazakAllahu khayran,\nAbdoulaye Mouhidine Sow\nDirector, Rewayah Academy", "langue_source": "en", "raison": "You are receiving this message because your organisation teaches the Qur’an and says so publicly.", "campagne": "prospection-v3", "type": "lettre", "segment": "en_oc", "temoin_sans_image": false, "image": {"src": "https://rewayahacademy.com/fr/assets/courriel-prospection-en.png", "alt": "For the students who cannot come. “The one who guides to good is like the one who does it.” Hadith narrated by at-Tirmidhi, no. 2670. Rewayah Academy.", "largeur": 600, "hauteur": 315}}'::jsonb, '2026-11-29T21:24:00+00:00'::timestamptz, 'prospection-v3:info@manawatumuslims.org.nz'),
    ('admin@iqra.school.nz', 'en', '{"sujet": "For the families who can’t make it to your madrasa", "corps": "Assalamu alaykum wa rahmatullah,\n\nYour centre teaches the Qur’an face to face, and nothing beats that when it’s possible. But some families miss out: the classes are full, the times don’t suit, or they live too far out.\n\nRewayah Academy is there for them: live online Qur’an classes in small groups, with the same teacher three times a week. We don’t replace your classes; we reach the children who can’t get to them.\n\nIf a family comes to mind, simply pass on this link:\nhttps://rewayahacademy.com/en/familles?ref=iqra-school-auckland\n\nThe Prophet ﷺ said: “The one who guides to good is like the one who does it.” (at-Tirmidhi)\n\nJazakAllahu khayran,\nAbdoulaye Mouhidine Sow\nDirector, Rewayah Academy", "langue_source": "en", "raison": "You are receiving this message because your organisation teaches the Qur’an and says so publicly.", "campagne": "prospection-v3", "type": "lettre", "segment": "en_oc", "temoin_sans_image": false, "image": {"src": "https://rewayahacademy.com/fr/assets/courriel-prospection-en.png", "alt": "For the students who cannot come. “The one who guides to good is like the one who does it.” Hadith narrated by at-Tirmidhi, no. 2670. Rewayah Academy.", "largeur": 600, "hauteur": 315}}'::jsonb, '2026-11-29T21:24:32+00:00'::timestamptz, 'prospection-v3:admin@iqra.school.nz'),
    ('uklatrust@gmail.com', 'en', '{"sujet": "In one sentence", "corps": "Assalamu alaykum,\n\nI wrote to you a few days ago; in one sentence: for the families in your community who can’t attend your classes in person, Rewayah Academy offers live online Qur’an classes as a complement. The link to pass on:\nhttps://rewayahacademy.com/en/familles?ref=umar-bin-khattab-learning\n\nJazakAllahu khayran,\nAbdoulaye Mouhidine Sow\nDirector, Rewayah Academy", "langue_source": "en", "raison": "You are receiving this message because your organisation teaches the Qur’an and says so publicly.", "campagne": "prospection-v3", "type": "relance", "segment": "en_oc", "temoin_sans_image": true}'::jsonb, '2026-11-29T21:24:54+00:00'::timestamptz, 'prospection-v3:uklatrust@gmail.com'),
