    ('info@masjidalmuhsinin.de', 'ar', '{"sujet": "في سطر واحد", "corps": "السلام عليكم ورحمة الله وبركاته،\n\nكتبت إليكم قبل أيام، وخلاصة رسالتي: للأسر التي لا تستطيع حضور حلقاتكم، تقدّم أكاديمية الرواية دروسًا في القرآن عن بُعد، مكمّلةً لما تقومون به. وهذا الرابط لمن أردتم أن ترسلوه إليه:\nhttps://rewayahacademy.com/ar/familles?ref=masjid-almuhsinin-leverkusen\n\nبارك الله فيكم،\nعبد الله محي الدين صو\nمدير أكاديمية الرواية", "langue_source": "ar", "raison": "وصلكم هذا البريد لأن مؤسستكم تعلّم القرآن وتعلن ذلك.", "campagne": "prospection-v3", "type": "relance", "segment": "ar", "temoin_sans_image": false}'::jsonb, '2026-11-30T10:16:24+00:00'::timestamptz, 'prospection-v3:info@masjidalmuhsinin.de'),
